package dev.kelmagic.server;
import dev.kelmagic.*;import dev.kelmagic.research.Research;import net.minecraft.server.level.ServerPlayer;import net.minecraft.core.BlockPos;import net.minecraft.world.level.block.*;import net.minecraft.world.level.ClipContext;import net.minecraft.world.phys.*;
public final class MagicTransformation {
 public static boolean cast(ServerPlayer p){var eye=p.getEyePosition();var hit=p.serverLevel().clip(new ClipContext(eye,eye.add(p.getLookAngle().scale(Config.RANGE.get())),ClipContext.Block.OUTLINE,ClipContext.Fluid.NONE,p));return hit.getType()==HitResult.Type.BLOCK&&transform(p,hit.getBlockPos());}
 public static boolean transform(ServerPlayer p,BlockPos pos){var old=p.serverLevel().getBlockState(pos);boolean torch=old.is(Blocks.TORCH)||old.is(Blocks.WALL_TORCH)||old.is(Blocks.REDSTONE_TORCH)||old.is(Blocks.REDSTONE_WALL_TORCH)||old.is(Blocks.SOUL_TORCH)||old.is(Blocks.SOUL_WALL_TORCH);boolean lantern=java.util.Set.of(Blocks.OCHRE_FROGLIGHT,Blocks.PEARLESCENT_FROGLIGHT,Blocks.VERDANT_FROGLIGHT,Blocks.SHROOMLIGHT,Blocks.REDSTONE_LAMP,Blocks.SEA_LANTERN,Blocks.GLOWSTONE).contains(old.getBlock());if(!torch&&!lantern)return false;var next=lantern?MagicLamps.DURABLE_LANTERN.get().defaultBlockState():old.hasProperty(WallTorchBlock.FACING)?MagicLamps.DURABLE_WALL.get().defaultBlockState().setValue(WallTorchBlock.FACING,old.getValue(WallTorchBlock.FACING)):MagicLamps.DURABLE_TORCH.get().defaultBlockState();if(!WorldSpells.place(p,pos,next,true))return false;Research.observe(p,torch?"transform:torch":"transform:lantern");p.serverLevel().sendParticles(net.minecraft.core.particles.ParticleTypes.END_ROD,pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5,12,.2,.2,.2,.02);return true;}
 private MagicTransformation(){}
}
